<?php
require_once __DIR__.'/includes/config.php';require_once __DIR__.'/includes/auth.php';sisatRequireRoles([1,2]);
function h($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}$error='';$ok='';
if($_SERVER['REQUEST_METHOD']==='POST'){$activo=(int)($_POST['activo_id']??0);$sede=(int)($_POST['sede_destino_id']??0);$piso=trim($_POST['piso_destino']??'');$oficina=trim($_POST['oficina_destino']??'');$depto=trim($_POST['departamento_destino']??'');$fecha=trim($_POST['fecha_movimiento']??'');$motivo=trim($_POST['motivo']??'');$obs=trim($_POST['observaciones']??'');try{if(!$activo||!$sede||$piso===''||$oficina===''||$depto===''||$motivo==='')throw new RuntimeException('Completa todos los campos obligatorios.');$dt=DateTime::createFromFormat('Y-m-d\TH:i',$fecha);if(!$dt||$dt->format('Y-m-d\TH:i')!==$fecha)throw new RuntimeException('Fecha u hora no válida.');$dbh->beginTransaction();$q=$dbh->prepare("SELECT a.ubicacion_id,a.estado,u.sede_id FROM activos a LEFT JOIN ubicaciones u ON u.id=a.ubicacion_id WHERE a.id=? FOR UPDATE");$q->execute([$activo]);$a=$q->fetch(PDO::FETCH_ASSOC);if(!$a||$a['estado']==='DADO_DE_BAJA_OBSOLETO')throw new RuntimeException('Activo inexistente o dado de baja.');if((int)$a['sede_id']===$sede)throw new RuntimeException('La sede destino debe ser diferente a la actual.');$q=$dbh->prepare("SELECT id FROM sedes WHERE id=? AND estado='ACTIVA'");$q->execute([$sede]);if(!$q->fetchColumn())throw new RuntimeException('Sede destino no disponible.');$ins=$dbh->prepare("INSERT INTO solicitudes_traslado(activo_id,ubicacion_origen_id,sede_destino_id,piso_destino,oficina_destino,departamento_destino,fecha_movimiento,motivo,observaciones,solicitado_por) VALUES(?,?,?,?,?,?,?,?,?,?)");$ins->execute([$activo,$a['ubicacion_id'],$sede,$piso,$oficina,$depto,$dt->format('Y-m-d H:i:s'),$motivo,$obs?:null,(int)$_SESSION['uid']]);$dbh->commit();$ok='Solicitud enviada al administrador. El activo no cambiará de ubicación hasta su aprobación.';}catch(Throwable $e){if($dbh->inTransaction())$dbh->rollBack();$error=$e->getMessage();}}
$activos=$dbh->query("SELECT id,codigo_inventario,descripcion FROM activos WHERE estado<>'DADO_DE_BAJA_OBSOLETO' ORDER BY codigo_inventario")->fetchAll(PDO::FETCH_ASSOC);$sedes=$dbh->query("SELECT id,nombre FROM sedes WHERE estado='ACTIVA' ORDER BY nombre")->fetchAll(PDO::FETCH_ASSOC);include __DIR__.'/includes/topbar.php';?>
<div class="content-wrapper"><div class="content-container"><?php include __DIR__.'/includes/leftbar.php';?><div class="main-page"><div class="container-fluid"><h2>Solicitar traslado de activo</h2><p>El movimiento queda pendiente hasta que el administrador lo apruebe.</p></div><section class="section"><div class="container-fluid"><div class="panel"><div class="panel-body"><?php if($error):?><div class="alert alert-danger"><?=h($error)?></div><?php endif;?><?php if($ok):?><div class="alert alert-success"><?=h($ok)?></div><?php endif;?><form method="post"><div class="form-group"><label>Activo *</label><select class="form-control" name="activo_id" required><option value="">Seleccione</option><?php foreach($activos as $a):?><option value="<?=$a['id']?>"><?=h($a['codigo_inventario'].' - '.$a['descripcion'])?></option><?php endforeach;?></select></div><div class="form-group"><label>Sede destino *</label><select class="form-control" name="sede_destino_id" required><option value="">Seleccione</option><?php foreach($sedes as $s):?><option value="<?=$s['id']?>"><?=h($s['nombre'])?></option><?php endforeach;?></select></div><div class="form-group"><label>Piso *</label><input class="form-control" name="piso_destino" maxlength="30" required></div><div class="form-group"><label>Oficina *</label><input class="form-control" name="oficina_destino" maxlength="150" required></div><div class="form-group"><label>Departamento / área *</label><input class="form-control" name="departamento_destino" maxlength="120" required></div><div class="form-group"><label>Fecha y hora *</label><input class="form-control" type="datetime-local" name="fecha_movimiento" value="<?=date('Y-m-d\TH:i')?>" required></div><div class="form-group"><label>Motivo *</label><textarea class="form-control" name="motivo" maxlength="255" required></textarea></div><div class="form-group"><label>Observaciones</label><textarea class="form-control" name="observaciones"></textarea></div><button class="btn btn-primary">Enviar solicitud</button></form></div></div></div></section></div></div></div><?php include __DIR__.'/includes/footer.php';?>
